  sql = `UPDATE conversation_state SET context = JSON_SET(COALESCE(context, JSON_OBJECT()), '$.medico', 'Cualquier doctor', '$.medico_cualquiera', true, '$.doctor_id', null), state = 'awaiting_dia_hora' WHERE phone = '${phone}';`;
